// One job per project x language chunk x 500-key page. Small jobs keep each worker call well inside n8n's memory.
const b = $input.first().json || {};
const projects = b.projects || (b.body && b.body.projects) || [];
if (!projects.length) { throw new Error('projects fetch failed: ' + JSON.stringify(b).slice(0, 300)); }
const CHUNK = 8;
const PAGE = 500;
const PSEUDO = /^(pst|ps|xx|zz|qps)$|pseudo|[_-]ps$/i;
const jobs = [];
for (const p of projects) {
  const st = p.statistics || {};
  const langs = st.languages || [];
  const total = Number(st.keys_total || st.keys || 0);
  const pages = Math.max(1, Math.ceil(total / PAGE));
  const baseId = p.base_language_id;
  const baseIso = p.base_language_iso || 'en';
  const tg = langs.filter(function (l) { return l.language_id !== baseId && !PSEUDO.test(String(l.language_iso || '')); });
  for (let i = 0; i < tg.length; i += CHUNK) {
    const part = tg.slice(i, i + CHUNK);
    for (let pg = 1; pg <= pages; pg++) {
      jobs.push({ json: { pid: p.project_id, name: p.name, base_iso: baseIso, page: pg,
        langs: part.map(function (l) { return l.language_iso; }).join(','),
        lang_ids: [baseId].concat(part.map(function (l) { return l.language_id; })).join(',') } });
    }
  }
}
return jobs;

// Aggregates worker results into a Slack summary + threaded detail. Read-only.
const res = $input.all().map(function (i) { return i.json || {}; });
const jobs = $('Build jobs').all().map(function (i) { return i.json; });
let hits = []; const errors = []; let scanned = 0;
res.forEach(function (r, i) {
  const j = jobs[i] || {};
  if (r.error || !Array.isArray(r.hits)) { errors.push((r.name || j.name) + ' [' + (r.langs || j.langs) + ']: ' + String(r.error || 'worker failed').slice(0, 120)); }
  hits = hits.concat(r.hits || []);
  scanned += r.keys_scanned || 0;
});
const seen = {};
hits = hits.filter(function (h) { const k = String(h.translation_id || (h.pid + ':' + h.key_id + ':' + h.iso)); if (seen[k]) { return false; } seen[k] = 1; return true; });
// "new since the last scheduled run" (static data is only saved by production runs)
const store = $getWorkflowStaticData('global');
const prev = store.ids || null; const now = {};
for (const h of hits) { const id = String(h.translation_id) + ':' + h.text; now[id] = 1; h.is_new = prev ? !prev[id] : null; }
store.ids = now; store.at = new Date().toISOString();
const projects = {}; const order = [];
for (const h of hits) { if (!projects[h.project]) { projects[h.project] = []; order.push(h.project); } projects[h.project].push(h); }
order.sort();
const pidOf = {}; for (const h of hits) { pidOf[h.project] = h.pid; }
const newCount = hits.filter(function (h) { return h.is_new === true; }).length;
let summary = '*Wrong-script / garbled text check* — ' + jobs.length + ' project/language batches, ' + scanned + ' key rows scanned\n';
summary += 'Flags translations with characters from a writing system the language does not use (e.g. Chinese 谋 inside Turkish "haz谋r!") or broken encoding (Ã©, â€™, �).\n\n';
if (!hits.length && !errors.length) { summary += ':white_check_mark: No wrong-script characters or garbled encoding in any translation.'; }
else if (!hits.length) { summary += ':white_check_mark: Nothing flagged in the batches that could be read.'; }
else {
  summary += ':rotating_light: *' + hits.length + ' translation' + (hits.length === 1 ? '' : 's') + ' flagged* in ' + order.length + ' project' + (order.length === 1 ? '' : 's') + ' — details in thread.';
  if (prev) { summary += '\n:new: ' + newCount + ' new since the last nightly run.'; }
}
if (errors.length) { summary += '\n:warning: could not read ' + errors.length + ' batch(es): ' + errors.slice(0, 5).join('; ') + (errors.length > 5 ? ' …' : ''); }
function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
const lines = [];
for (const p of order) {
  let block = '<https://app.lokalise.com/project/' + pidOf[p] + '/|' + esc(p).replace(/\|/g, ' ') + '> — ' + projects[p].length;
  for (const h of projects[p].slice(0, 40)) {
    block += '\n    • ' + h.iso + ' `' + esc(h.key) + '` — ' + esc(h.chars) + ' — "' + esc(h.text.slice(0, 120)) + '"' +
      (h.modified_by ? ' _(' + String(h.modified_at).slice(0, 10) + ', ' + esc(h.modified_by) + ')_' : '') + (h.is_new ? ' :new:' : '');
  }
  if (projects[p].length > 40) { block += '\n    … +' + (projects[p].length - 40) + ' more'; }
  lines.push(block);
}
const chunks = []; let cur = '';
for (const l of lines) {
  const piece = l.length > 3400 ? l.slice(0, 3390) + '…' : l;
  if (cur && (cur.length + piece.length + 2) > 3400) { chunks.push(cur); cur = ''; }
  cur += (cur ? '\n\n' : '') + piece;
}
if (cur) { chunks.push(cur); }
return [{ json: { summary: summary, chunks: chunks, total: hits.length, new_count: newCount, errors: errors, batches: jobs.length, keys_scanned: scanned, hits: hits } }];

// Manual runs (tests, ad hoc checks from Claude) never post to Slack; scheduled runs do.
if ($execution.mode === 'manual') { return []; }
return $input.all();

const built = $('Report').first().json;
const posted = $input.first().json || {};
const ts = posted.ts || (posted.message && posted.message.ts) || null;
return (built.chunks || []).map(function (c) { return { json: { text: c, thread_ts: ts } }; });
